// Verifies the HMAC signature Convex puts on every webhook call:
//   X-LendLoop-Signature: v1=HMAC_SHA256(secret, `${timestamp}.${rawBody}`)
// The secret is read from the LENDLOOP_WEBHOOK_SECRET environment variable,
// so it never appears in this workflow's JSON.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;

const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret || secret.length < 32) {
  throw new Error('LENDLOOP_WEBHOOK_SECRET is not configured');
}

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');
const rawBody = item.binary && item.binary.data
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')
  : '';

const reject = (reason) => [{ json: { valid: false, reason } }];

if (!/^\d{1,12}$/.test(timestamp)) return reject('missing_timestamp');
const skew = Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp));
if (skew > MAX_SKEW_SECONDS) return reject('stale_timestamp');
if (!/^v1=[0-9a-f]{64}$/.test(signature)) return reject('malformed_signature');

const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest();
const provided = Buffer.from(signature.slice(3), 'hex');
if (!crypto.timingSafeEqual(expected, provided)) return reject('signature_mismatch');

let payload;
try {
  payload = JSON.parse(rawBody);
} catch (e) {
  return reject('invalid_json');
}
if (payload.version !== 1 || !payload.deliveryId || !payload.recipient || !payload.loan) {
  return reject('unexpected_payload');
}

// Pass on only the verified payload; request headers (IPs etc.) are dropped.
return [{ json: { valid: true, payload } }];

// Turns a loan event into a short message. Uses only the fields Convex sent:
// recipient email + first name, the other party's first name, tool and dates.
const p = $json.payload;
const tool = p.loan.toolName;
const dates = p.loan.startDate === p.loan.endDate
  ? p.loan.startDate
  : `${p.loan.startDate} to ${p.loan.endDate}`;
const other = p.counterparty.firstName;

const templates = {
  request_created: [`New request for your ${tool}`, `${other} would like to borrow your ${tool} (${dates}). Approve or decline it in LendLoop.`],
  request_approved: [`Request approved: ${tool}`, `${other} approved your request to borrow the ${tool} (${dates}).`],
  request_declined: [`Request declined: ${tool}`, `${other} can't lend the ${tool} for ${dates} this time.`],
  request_cancelled: [`Request cancelled: ${tool}`, `The request for the ${tool} (${dates}) was cancelled.`],
  loan_returned: [`Thanks for returning the ${tool}`, `${other} confirmed the ${tool} is back. Thanks for being a good neighbor!`],
};
const template = templates[p.event];
if (!template) throw new Error(`Unknown LendLoop event type: ${p.event}`);

const [subject, line] = template;
const link = p.actionUrl ? `\n\nOpen LendLoop: ${p.actionUrl}` : '';
return {
  json: {
    kind: 'request_notification',
    idempotencyKey: p.idempotencyKey,
    loanId: p.loan.id,
    to: p.recipient.email,
    subject,
    text: `Hi ${p.recipient.firstName},\n\n${line}${link}\n\n- LendLoop`,
  },
};

// MOCK notification channel: logs the message instead of sending it.
// To send real email, replace this node with a "Send Email" node that uses
// an SMTP credential (to: {{ $json.to }}, subject/text from this item).
// The address is masked so logs do not collect personal data.
const masked = String($json.to).replace(/^(.).*(@.*)$/, '$1***$2');
console.log(`[LendLoop] ${$json.kind} -> ${masked}: "${$json.subject}"`);
return { json: { ...$json, status: 'sent', channel: 'mock-log' } };

// Reached via the error output of the send node (after its retries).
// The original message comes from the paired item of "Compose message", so the
// failure is recorded against the right loan even if the error item is bare.
const original = $('Compose message').item.json;
const error = $json.error;
const message = typeof error === 'string' ? error : (error && error.message) || 'Send failed';
return {
  json: {
    kind: original.kind,
    idempotencyKey: original.idempotencyKey,
    loanId: original.loanId,
    status: 'failed',
    channel: 'mock-log',
    detail: String(message).replace(/[^\s@]+@[^\s@]+/g, '[email]').slice(0, 300),
  },
};

// Signs the write-back to Convex:
//   X-LendLoop-Signature: v1=HMAC_SHA256(secret, `${ts}.POST.${path}.${body}`)
// The body is sent as raw text so the signed bytes are exactly what arrives.
const crypto = require('crypto');
const secret = $env.LENDLOOP_CALLBACK_SECRET;
if (!secret || secret.length < 32) throw new Error('LENDLOOP_CALLBACK_SECRET is not configured');

const path = '/n8n/automation-events';
const body = JSON.stringify({
  idempotencyKey: $json.idempotencyKey, // same key on every retry => no duplicates
  loanId: $json.loanId,
  kind: $json.kind,
  status: $json.status,
  channel: $json.channel,
  detail: $json.detail,
});
const ts = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${ts}.POST.${path}.${body}`).digest('hex');
return { json: { status: $json.status, path, body, ts, signature } };
